{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara studies a torn map of the ruined city.",
      "visual_description": "A windswept hill at dusk overlooks a shattered skyline of broken spires; ink-stained coat flapping, a brass compass spinning wildly in her hand.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of the road ahead.",
      "visual_description": "A battered oil lamp held aloft, its single flame-eye flaring orange, casting long shadows across cracked cobblestones near a fallen city sign.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Tin fox sniffs the wind at the broken gates.",
      "visual_description": "A small clockwork fox with a key-wind tail crouches before enormous splintered castle gates, blue glass eyes glinting in moonlight.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "The glass diver arrives through a shattered window.",
      "visual_description": "A figure in a clear diving helmet emerges headfirst from a tall stained-glass pane, coat shimmering with reflected city lights and ember sparks.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "They pass faded royal banners hanging in ruin.",
      "visual_description": "Tattered crimson and gold banners drape from collapsed archways; the team picks its way over rubble, the lamp's eye lighting heraldic crests.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "Tin fox darts past an armored patrol unseen.",
      "visual_description": "Heavy plated boots stomp through a courtyard while a small metal fox slips between barrels, key-wind tail spinning silently.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "They discover the sleeping tax collector at a checkpoint.",
      "visual_description": "A plump official slumped over a tollgate desk, ledger book as a pillow, stamped papers stuck to his sleeves, drool on a wax seal.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "The lamp warns against entering the cursed tower.",
      "visual_description": "A leaning black tower wreathed in violet smoke; the oracle lamp's eye narrows, projecting glowing warning runes onto the doorway.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "Mara redraws the route on her compass map.",
      "visual_description": "Kneeling by a fountain choked with ash, ink-stained fingers sketch new lines onto vellum while the brass compass needle trembles.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "The glass diver swims through a tall mirror.",
      "visual_description": "A floor-length mirror ripples like water as the coated figure dives through, helmet reflecting the rescue target's silhouette beyond.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "Frightened whispers drift from boarded windows.",
      "visual_description": "Narrow alley of shuttered houses; pale faces peek through cracks while the lamp casts a soft halo and the cartographer raises a calming hand.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "A rumored beast roars in the distance.",
      "visual_description": "A vast clawed shadow stretches over rooftops against a smoking red sky; the tin fox flattens its ears, key-wind tail frozen mid-tick.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "They reach a sealed magic door humming with runes.",
      "visual_description": "An iron door inlaid with glowing sigils pulses blue; the oracle lamp's flame bends toward the lock, reading its riddle aloud.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 14,
      "caption": "The sleeping tax collector mumbles the secret password.",
      "visual_description": "Half-snoring on the cartographer's shoulder, the official mutters in his sleep as rune-light flickers; stamped papers drift to the floor.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "The glass diver carries the rescued one through reflections.",
      "visual_description": "Inside a hall of cracked mirrors, the diver clutches a bundled figure, leaping from pane to pane in a trail of silver ripples.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "Armored patrols converge on the courtyard.",
      "visual_description": "Torchlight floods a fountain plaza; plate-armored shapes close in as the tin fox skids between their legs, leading them in circles.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 17,
      "caption": "They sprint across the cracking stone bridge.",
      "visual_description": "A long arched bridge over a dark chasm splinters underfoot; the lamp swings wildly, the diver's coat flares, the cartographer points ahead.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "Safe at last beyond the ruined city.",
      "visual_description": "Dawn breaks over a quiet meadow on the far bank; the team rests on a grassy slope, the tax collector still asleep, brass compass finally still.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

